const team = { name: "Blue", members: ["Ada"], lead: { name: "Ben" } };
const clone = { ...team, lead: { ...team.lead } };

clone.name = "Red";
clone.members.push("Cy");
clone.lead.name = "Dee";

console.log(team.name);
console.log(team.members.length);
console.log(team.lead.name);
console.log(clone.members === team.members);
